import SwiftUI

extension SwiftForgeTheme {

    /// Soft and luminous: violet-to-teal gradient buttons, pill-shaped
    /// controls, generously rounded cards (24 pt) with large tinted shadows,
    /// and floating surfaces of translucent glass.
    ///
    /// Glass is reserved for overlays — toasts, loading panels — that float
    /// above moving content; cards stay opaque, because glass on a still,
    /// plain background only looks gray. With Reduce Transparency on, glass
    /// becomes opaque, and contrast is verified against that opaque color.
    /// Text uses SF Rounded, spacing is airy, motion has a gentle bounce, and
    /// text fields are filled rather than outlined.
    public static let aurora: SwiftForgeTheme = {
        typealias P = Palette.Aurora
        let accent = SwiftForgeToneColors(
            solid: SwiftForgeColor(
                light: P.Violet.s600, dark: P.lavender, lightHighContrast: P.Violet.s800, darkHighContrast: P.Violet.s200),
            onSolid: SwiftForgeColor(light: Palette.white, dark: P.ink, darkHighContrast: Palette.black),
            text: SwiftForgeColor(
                light: P.Violet.s600, dark: P.Violet.s300, lightHighContrast: P.Violet.s800, darkHighContrast: P.Violet.s200),
            subtle: SwiftForgeColor(
                light: P.Violet.s100, dark: P.Violet.s950, lightHighContrast: P.Violet.s200, darkHighContrast: P.Violet.s900),
            solidFill: .linearGradient(
                [
                    SwiftForgeColor(
                        light: P.Violet.s600, dark: P.lavender, lightHighContrast: P.Violet.s800, darkHighContrast: P.Violet.s200),
                    SwiftForgeColor(
                        light: P.Teal.s700, dark: P.aqua, lightHighContrast: P.Teal.s800, darkHighContrast: P.Teal.s200),
                ], startPoint: .leading, endPoint: .trailing)
        )
        let colors = SwiftForgeColors(
            canvas: SwiftForgeColor(light: P.mist, dark: P.dusk),
            surface: SwiftForgeColor(light: Palette.white, dark: P.nightPanel),
            surfaceRaised: SwiftForgeColor(light: Palette.white, dark: P.nightLift),
            fillMuted: SwiftForgeColor(
                light: P.Haze.s100, dark: P.Haze.s900, lightHighContrast: P.Haze.s200, darkHighContrast: P.Haze.s800),
            textPrimary: SwiftForgeColor(
                light: P.Haze.s950, dark: P.Haze.s50, lightHighContrast: Palette.black, darkHighContrast: Palette.white),
            textSecondary: SwiftForgeColor(
                light: P.Haze.s700, dark: P.Haze.s300, lightHighContrast: P.Haze.s800, darkHighContrast: P.Haze.s200),
            borderSubtle: SwiftForgeColor(
                light: P.Haze.s200, dark: P.Haze.s800, lightHighContrast: P.Haze.s400, darkHighContrast: P.Haze.s600),
            borderStrong: SwiftForgeColor(
                light: P.Haze.s500, dark: P.Haze.s500, lightHighContrast: P.Haze.s700, darkHighContrast: P.Haze.s300),
            focusRing: accent.text,
            pressedOverlay: SharedTokens.pressedOverlay,
            accent: accent,
            neutral: SwiftForgeToneColors(
                solid: SwiftForgeColor(
                    light: P.Haze.s800, dark: P.Haze.s300, lightHighContrast: P.Haze.s900, darkHighContrast: P.Haze.s200),
                onSolid: SwiftForgeColor(light: Palette.white, dark: P.ink, darkHighContrast: Palette.black),
                text: SwiftForgeColor(
                    light: P.Haze.s700, dark: P.Haze.s300, lightHighContrast: P.Haze.s800, darkHighContrast: P.Haze.s200),
                subtle: SwiftForgeColor(
                    light: P.Haze.s100, dark: P.Haze.s900, lightHighContrast: P.Haze.s200, darkHighContrast: P.Haze.s800)
            ),
            info: SwiftForgeToneColors(
                solid: SwiftForgeColor(
                    light: P.Sky.s700, dark: P.Sky.s300, lightHighContrast: P.Sky.s800, darkHighContrast: P.Sky.s200),
                onSolid: SwiftForgeColor(light: Palette.white, dark: P.ink, darkHighContrast: Palette.black),
                text: SwiftForgeColor(
                    light: P.Sky.s700, dark: P.Sky.s300, lightHighContrast: P.Sky.s800, darkHighContrast: P.Sky.s200),
                subtle: SwiftForgeColor(
                    light: P.Sky.s100, dark: P.Sky.s950, lightHighContrast: P.Sky.s200, darkHighContrast: P.Sky.s900)
            ),
            success: SwiftForgeToneColors(
                solid: SwiftForgeColor(
                    light: P.Mint.s700, dark: P.Mint.s300, lightHighContrast: P.Mint.s800, darkHighContrast: P.Mint.s200),
                onSolid: SwiftForgeColor(light: Palette.white, dark: P.ink, darkHighContrast: Palette.black),
                text: SwiftForgeColor(
                    light: P.Mint.s700, dark: P.Mint.s300, lightHighContrast: P.Mint.s800, darkHighContrast: P.Mint.s200),
                subtle: SwiftForgeColor(
                    light: P.Mint.s100, dark: P.Mint.s950, lightHighContrast: P.Mint.s200, darkHighContrast: P.Mint.s900)
            ),
            warning: SwiftForgeToneColors(
                solid: SwiftForgeColor(
                    light: P.Honey.s300, dark: P.Honey.s300, lightHighContrast: P.Honey.s400, darkHighContrast: P.Honey.s200),
                onSolid: SwiftForgeColor(light: Palette.black, dark: P.ink, darkHighContrast: Palette.black),
                text: SwiftForgeColor(
                    light: P.Honey.s700, dark: P.Honey.s300, lightHighContrast: P.Honey.s800, darkHighContrast: P.Honey.s200),
                subtle: SwiftForgeColor(
                    light: P.Honey.s100, dark: P.Honey.s950, lightHighContrast: P.Honey.s200, darkHighContrast: P.Honey.s900)
            ),
            danger: SwiftForgeToneColors(
                solid: SwiftForgeColor(
                    light: P.Coral.s700, dark: P.Coral.s300, lightHighContrast: P.Coral.s800, darkHighContrast: P.Coral.s200),
                onSolid: SwiftForgeColor(light: Palette.white, dark: P.ink, darkHighContrast: Palette.black),
                text: SwiftForgeColor(
                    light: P.Coral.s700, dark: P.Coral.s300, lightHighContrast: P.Coral.s800, darkHighContrast: P.Coral.s200),
                subtle: SwiftForgeColor(
                    light: P.Coral.s100, dark: P.Coral.s950, lightHighContrast: P.Coral.s200, darkHighContrast: P.Coral.s900)
            )
        )
        return SwiftForgeTheme(
            id: "aurora",
            displayName: "Aurora",
            colors: colors,
            typography: SwiftForgeTypography.standard.updating(SwiftForgeTypography.allRoles) { $0.design = .rounded },
            spacing: SwiftForgeSpacing(
                xxxs: 2, xxs: 4, xs: 8, sm: 12, md: 16, lg: 24, xl: 28, xxl: 36, xxxl: 48,
                screenHorizontal: 20, section: 28, component: 14, cardPadding: 20
            ),
            radius: SwiftForgeRadius(
                xs: 6, sm: 10, md: 14, lg: 18, xl: 24, xxl: 32,
                control: 16, controlSmall: 12, card: 24, sheet: 32
            ),
            sizes: SwiftForgeSizes(
                minimumHitTarget: 44, controlHeightSmall: 34, controlHeightRegular: 46, controlHeightLarge: 54,
                iconSmall: 16, iconRegular: 20, iconLarge: 24
            ),
            elevation: SwiftForgeElevation(
                low: SwiftForgeShadow(
                    color: SharedTokens.shadowColor(light: P.Violet.s600, 0.18, dark: Palette.black, 0.45), radius: 10, y: 4),
                medium: SwiftForgeShadow(
                    color: SharedTokens.shadowColor(light: P.Violet.s600, 0.16, dark: Palette.black, 0.55), radius: 24, y: 10),
                high: SwiftForgeShadow(
                    color: SharedTokens.shadowColor(light: P.Violet.s700, 0.22, dark: Palette.black, 0.65), radius: 40, y: 18),
                raisedSurfacesHaveBorder: false
            ),
            motion: SwiftForgeMotion(
                fast: SwiftForgeMotionToken(duration: 0.25, bounce: 0.25),
                standard: SwiftForgeMotionToken(duration: 0.4, bounce: 0.15),
                emphasized: SwiftForgeMotionToken(duration: 0.55, bounce: 0.3),
                shimmerDuration: 1.6,
                pressedScale: 0.95
            ),
            components: SwiftForgeComponentTokens(
                button: SwiftForgeButtonTokens(cornerRadius: SwiftForgeRadius.capsule, elevation: .low),
                surface: SwiftForgeSurfaceTokens(fills: [.overlay: .material(.regular, fallback: colors.surfaceRaised)]),
                field: SwiftForgeFieldTokens(style: .filled),
                banner: SwiftForgeBannerTokens(cornerRadius: 20),
                progress: SwiftForgeProgressTokens(barHeight: 6, barHeightLarge: 10),
                chip: SwiftForgeChipTokens(cornerRadius: SwiftForgeRadius.capsule),
                segmentedControl: SwiftForgeSegmentedControlTokens(cornerRadius: SwiftForgeRadius.capsule, indicatorInset: 3),
                slider: SwiftForgeSliderTokens(trackHeight: 6, thumbDiameter: 26),
                emptyState: SwiftForgeEmptyStateTokens(iconSize: 56)
            )
        )
    }()
}
